        "code": "import math\n\nclass KalmanFilterPairsTracker:\n    def __init__(self, delta_q=1e-4, r_noise=1e-2):\n        # State vector: [beta] (simplified 1D slope tracker)\n        self.beta = 1.0\n        self.p_cov = 1.0\n        self.q = delta_q # Process noise variance\n        self.r = r_noise # Measurement noise variance\n\n    def update(self, price_x, price_y):\n        # 1. Predict stage\n        # beta_prior = beta_post\n        p_prior = self.p_cov + self.q\n        \n        # 2. Measurement update\n        # H = [price_x]\n        y_pred = price_x * self.beta\n        error = price_y - y_pred # Innovation residual\n        \n        # Innovation variance S = H * P * H^T + R\n        s_var = (price_x * p_prior * price_x) + self.r\n        \n        # Kalman Gain K = P * H^T * S^-1\n        k_gain = (p_prior * price_x) / s_var\n        \n        # Update state and covariance\n        self.beta += k_gain * error\n        self.p_cov = (1.0 - k_gain * price_x) * p_prior\n        \n        # Standardized innovation Z-score\n        z_score = error / math.sqrt(max(1e-6, s_var))\n        \n        return {\n            \"beta\": round(self.beta, 4),\n            \"error\": round(error, 4),\n            \"z_score\": round(z_score, 2),\n            \"kalman_gain\": round(k_gain, 6)\n        }\n\nkf = KalmanFilterPairsTracker(delta_q=1e-4, r_noise=1e-2)\n# Stream price pairs where true beta shifts from 1.0 to 1.5\nprices = [(100.0, 100.5), (101.0, 120.0), (102.0, 140.0), (103.0, 154.5)]\nfor px, py in prices:\n    step = kf.update(px, py)\n    print(f\"X={px}, Y={py} -> updated Beta={step['beta']}, Z-score={step['z_score']}\")",
