        "code": "import math\n\nclass RobustIVSolver:\n    @staticmethod\n    def solve_iv(s, k, t, r, market_price, max_iter=20, tol=1e-5):\n        # Fallback bounds\n        lower_vol = 0.001\n        upper_vol = 3.0\n        \n        # Initial seed\n        sigma = 0.20\n        if abs(s - k) / s < 0.05:\n            sigma = (math.sqrt(2.0 * math.pi / t) * (market_price / s)) if t > 0 else 0.20\n            sigma = max(lower_vol, min(upper_vol, sigma))\n            \n        for i in range(max_iter):\n            d1 = (math.log(s / k) + (r + 0.5 * (sigma ** 2)) * t) / (sigma * math.sqrt(t))\n            d2 = d1 - sigma * math.sqrt(t)\n            c_calc = s * (1.0 + math.erf(d1 / math.sqrt(2.0))) / 2.0 - k * math.exp(-r * t) * (1.0 + math.erf(d2 / math.sqrt(2.0))) / 2.0\n            diff = c_calc - market_price\n            \n            if abs(diff) < tol:\n                return {\"iv\": round(sigma, 4), \"iterations\": i + 1, \"status\": \"CONVERGED\"}\n                \n            vega = s * math.sqrt(t) * (1.0 / math.sqrt(2.0 * math.pi)) * math.exp(-0.5 * (d1 ** 2))\n            \n            if vega > 1e-4:\n                sigma = sigma - diff / vega\n                sigma = max(lower_vol, min(upper_vol, sigma))\n            else:\n                # Bisection step if Vega is too flat\n                if diff > 0:\n                    upper_vol = sigma\n                else:\n                    lower_vol = sigma\n                sigma = (lower_vol + upper_vol) / 2.0\n                \n        return {\"iv\": round(sigma, 4), \"iterations\": max_iter, \"status\": \"MAX_ITER_REACHED\"}\n\nres = RobustIVSolver.solve_iv(s=100.0, k=100.0, t=0.5, r=0.05, market_price=6.887)\nprint(\"Newton-Raphson IV Calibration Result:\", res[\"status\"])\nprint(f\"Calibrated Implied Volatility: {res['iv'] * 100}% in {res['iterations']} iterations\")",
