        "code": "import math\n\nclass DiscreteDeltaHedgeSimulator:\n    @staticmethod\n    def simulate_hedged_path(spot_path, strike, t_total, r, vol, cost_bps=10):\n        n = len(spot_path) - 1\n        dt = t_total / n\n        shares_held = 0.0\n        cash = 0.0\n        total_costs = 0.0\n        \n        # Sell 1 Call Option at initial BSM price\n        s0 = spot_path[0]\n        d1 = (math.log(s0 / strike) + (r + 0.5 * (vol ** 2)) * t_total) / (vol * math.sqrt(t_total))\n        c0 = s0 * (1.0 + math.erf(d1 / math.sqrt(2.0))) / 2.0 - strike * math.exp(-r * t_total) * (1.0 + math.erf((d1 - vol * math.sqrt(t_total)) / math.sqrt(2.0))) / 2.0\n        cash += c0\n        \n        for k in range(n):\n            s_k = spot_path[k]\n            t_rem = max(1e-4, t_total - k * dt)\n            d1_k = (math.log(s_k / strike) + (r + 0.5 * (vol ** 2)) * t_rem) / (vol * math.sqrt(t_rem))\n            delta_target = (1.0 + math.erf(d1_k / math.sqrt(2.0))) / 2.0\n            \n            # Rebalance stock\n            trade_shares = delta_target - shares_held\n            tx_cost = abs(trade_shares) * s_k * (cost_bps / 10000.0)\n            cash -= (trade_shares * s_k + tx_cost)\n            total_costs += tx_cost\n            shares_held = delta_target\n            \n        # Settle at maturity\n        s_end = spot_path[-1]\n        option_payoff = max(0.0, s_end - strike)\n        cash += shares_held * s_end - option_payoff\n        \n        return {\n            \"initial_premium_collected\": round(c0, 2),\n            \"final_net_pnl\": round(cash, 2),\n            \"total_transaction_costs\": round(total_costs, 2),\n            \"settlement_spot\": round(s_end, 2)\n        }\n\npath = [100.0, 101.5, 99.8, 102.0, 103.5] # Synthetic price path\nsim = DiscreteDeltaHedgeSimulator.simulate_hedged_path(path, strike=100.0, t_total=0.25, r=0.05, vol=0.20)\nprint(\"Discrete Delta Hedging Simulation Result:\")\nprint(f\"Premium: ${sim['initial_premium_collected']} | Final Hedged PnL: ${sim['final_net_pnl']}\")\nprint(f\"Transaction Costs Paid: ${sim['total_transaction_costs']}\")",
