        "code": "import math\n\nclass IntegratedOptionsExecutionEngine:\n    def __init__(self, spot, rate=0.05, delta_band=50.0):\n        self.spot = spot\n        self.rate = rate\n        self.delta_band = delta_band\n        self.stock_shares = 0.0\n        self.options = [] # list of {\"strike\", \"t\", \"vol\", \"qty\", \"is_call\"}\n\n    def add_option_position(self, strike, t, vol, qty, is_call=True):\n        self.options.append({\"strike\": strike, \"t\": t, \"vol\": vol, \"qty\": qty, \"is_call\": is_call})\n\n    def evaluate_portfolio_delta(self):\n        total_options_delta = 0.0\n        for opt in self.options:\n            k = opt[\"strike\"]\n            t = opt[\"t\"]\n            v = opt[\"vol\"]\n            qty = opt[\"qty\"]\n            is_c = opt[\"is_call\"]\n            \n            d1 = (math.log(self.spot / k) + (self.rate + 0.5 * (v ** 2)) * t) / (v * math.sqrt(t))\n            norm_d1 = (1.0 + math.erf(d1 / math.sqrt(2.0))) / 2.0\n            delta_single = norm_d1 if is_c else (norm_d1 - 1.0)\n            total_options_delta += delta_single * qty\n            \n        net_delta = total_options_delta + self.stock_shares\n        \n        # Check band hedging condition\n        hedge_order = 0.0\n        if abs(net_delta) > self.delta_band:\n            hedge_order = -net_delta\n            self.stock_shares += hedge_order\n            \n        return {\n            \"options_delta\": round(total_options_delta, 1),\n            \"stock_shares\": round(self.stock_shares, 1),\n            \"net_delta_before_hedge\": round(net_delta, 1),\n            \"hedge_order_executed\": round(hedge_order, 1)\n        }\n\nengine = IntegratedOptionsExecutionEngine(spot=100.0, delta_band=50.0)\n# Sell 500 ATM Calls (5 contracts of 100 shares)\nengine.add_option_position(strike=100.0, t=0.5, vol=0.20, qty=-500, is_call=True)\nres1 = engine.evaluate_portfolio_delta()\nprint(\"Initial Position (Short 500 Calls):\")\nprint(f\"Options Delta: {res1['options_delta']} | Hedge Executed: {res1['hedge_order_executed']} shares\")\nprint(f\"Stock Shares Held After Hedge: {res1['stock_shares']}\")",
